//! relay: a small Tokio service. Add modules below.

pub mod config;
pub mod profiles;

use std::collections::HashMap;
use std::future::Future;
use std::time::{SystemTime, UNIX_EPOCH};

use tokio::sync::RwLock;
use tokio::time::{Duration, Instant};

/// A user profile as served by the backend and shown on the team page.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Profile {
    pub id: String,
    pub name: String,
    pub team: String,
    pub email: String,
}

#[derive(Debug, thiserror::Error)]
pub enum BackendError {
    #[error("profile not found: {0}")]
    NotFound(String),
    #[error("backend error: {0}")]
    Other(String),
}

/// Source of truth for profile data. Implementations talk to whatever
/// upstream store actually holds profiles (HTTP API, database, etc).
pub trait ProfileBackend: Send + Sync {
    fn fetch(&self, id: &str) -> impl Future<Output = Result<Profile, BackendError>> + Send;
}

struct CacheEntry {
    profile: Profile,
    inserted_at: Instant,
}

/// Loads profiles through a `ProfileBackend`, caching results in memory
/// for `ttl` so repeated lookups (e.g. rendering the team page) don't
/// keep hitting the backend.
pub struct ProfileService<B: ProfileBackend> {
    backend: B,
    ttl: Duration,
    cache: RwLock<HashMap<String, CacheEntry>>,
}

impl<B: ProfileBackend> ProfileService<B> {
    pub fn new(backend: B, ttl: Duration) -> Self {
        Self {
            backend,
            ttl,
            cache: RwLock::new(HashMap::new()),
        }
    }

    /// Loads a single profile, serving from cache when the cached entry
    /// hasn't exceeded its TTL yet.
    pub async fn load(&self, id: &str) -> Result<Profile, BackendError> {
        if let Some(profile) = self.cached(id).await {
            return Ok(profile);
        }

        let profile = self.backend.fetch(id).await?;
        self.cache.write().await.insert(
            id.to_string(),
            CacheEntry {
                profile: profile.clone(),
                inserted_at: Instant::now(),
            },
        );
        Ok(profile)
    }

    /// Loads every id in `ids`, preserving order and pairing each id with
    /// its result so callers (e.g. the team page) can show partial failures.
    pub async fn load_many(&self, ids: &[String]) -> Vec<(String, Result<Profile, BackendError>)> {
        let mut results = Vec::with_capacity(ids.len());
        for id in ids {
            let result = self.load(id).await;
            results.push((id.clone(), result));
        }
        results
    }

    async fn cached(&self, id: &str) -> Option<Profile> {
        let cache = self.cache.read().await;
        let entry = cache.get(id)?;
        if entry.inserted_at.elapsed() < self.ttl {
            Some(entry.profile.clone())
        } else {
            None
        }
    }
}

/// Credentials for calling the upstream profile API, including the
/// currently held access token and when it expires.
#[derive(Debug, Clone)]
pub struct ApiCredentials {
    pub client_id: String,
    pub client_secret: String,
    pub access_token: String,
    pub expires_at: i64,
}

impl ApiCredentials {
    /// Seconds remaining before `access_token` expires, clamped to zero
    /// once it has already expired.
    pub fn seconds_until_expiry(&self) -> i64 {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system time before unix epoch")
            .as_secs() as i64;
        (self.expires_at - now).max(0)
    }
}

/// A parameterized SQL statement: `sql` uses positional `?N` placeholders,
/// `params` holds the values to bind in order. Keeping the two separate
/// (rather than formatting values into the query text) is what keeps this
/// safe against SQL injection from `name_prefix` and `team`.
pub struct ProfileSearchQuery {
    pub sql: String,
    pub params: Vec<String>,
}

/// Builds the SELECT statement the reporting job runs against SQLite to
/// find profiles whose name starts with `name_prefix` on a given `team`.
pub fn profile_search_sql(name_prefix: &str, team: &str) -> ProfileSearchQuery {
    ProfileSearchQuery {
        sql: "SELECT id, name, team, email FROM profiles \
              WHERE name LIKE ?1 AND team = ?2 \
              ORDER BY name"
            .to_string(),
        params: vec![format!("{name_prefix}%"), team.to_string()],
    }
}

use std::collections::HashMap;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

use relay::profiles::{
    profile_search_sql, ApiCredentials, BackendError, Profile, ProfileBackend, ProfileService,
};
use tokio::time::Duration;

struct FakeBackend {
    profiles: Mutex<HashMap<String, Profile>>,
    calls: Arc<AtomicUsize>,
}

impl FakeBackend {
    fn new(profiles: Vec<Profile>, calls: Arc<AtomicUsize>) -> Self {
        Self {
            profiles: Mutex::new(profiles.into_iter().map(|p| (p.id.clone(), p)).collect()),
            calls,
        }
    }
}

impl ProfileBackend for FakeBackend {
    async fn fetch(&self, id: &str) -> Result<Profile, BackendError> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        self.profiles
            .lock()
            .unwrap()
            .get(id)
            .cloned()
            .ok_or_else(|| BackendError::NotFound(id.to_string()))
    }
}

fn sample_profile(id: &str) -> Profile {
    Profile {
        id: id.to_string(),
        name: format!("User {id}"),
        team: "eng".to_string(),
        email: format!("{id}@example.com"),
    }
}

#[tokio::test]
async fn load_fetches_and_caches() {
    let calls = Arc::new(AtomicUsize::new(0));
    let backend = FakeBackend::new(vec![sample_profile("1")], calls.clone());
    let service = ProfileService::new(backend, Duration::from_secs(60));

    let first = service.load("1").await.unwrap();
    assert_eq!(first, sample_profile("1"));

    let second = service.load("1").await.unwrap();
    assert_eq!(second, sample_profile("1"));

    assert_eq!(calls.load(Ordering::SeqCst), 1);
}

#[tokio::test]
async fn load_propagates_not_found() {
    let backend = FakeBackend::new(vec![], Arc::new(AtomicUsize::new(0)));
    let service = ProfileService::new(backend, Duration::from_secs(60));

    let err = service.load("missing").await.unwrap_err();
    assert!(matches!(err, BackendError::NotFound(id) if id == "missing"));
}

#[tokio::test(start_paused = true)]
async fn cache_entries_expire_after_ttl() {
    let calls = Arc::new(AtomicUsize::new(0));
    let backend = FakeBackend::new(vec![sample_profile("1")], calls.clone());
    let service = ProfileService::new(backend, Duration::from_secs(30));

    service.load("1").await.unwrap();
    assert_eq!(calls.load(Ordering::SeqCst), 1);

    tokio::time::advance(Duration::from_secs(10)).await;
    service.load("1").await.unwrap();
    assert_eq!(calls.load(Ordering::SeqCst), 1, "still within TTL");

    tokio::time::advance(Duration::from_secs(21)).await;
    service.load("1").await.unwrap();
    assert_eq!(calls.load(Ordering::SeqCst), 2, "TTL expired, refetched");
}

#[tokio::test]
async fn load_many_preserves_order_and_reports_partial_failures() {
    let calls = Arc::new(AtomicUsize::new(0));
    let backend = FakeBackend::new(vec![sample_profile("1"), sample_profile("2")], calls);
    let service = ProfileService::new(backend, Duration::from_secs(60));

    let ids = vec!["1".to_string(), "missing".to_string(), "2".to_string()];
    let results = service.load_many(&ids).await;

    assert_eq!(results.len(), 3);
    assert_eq!(results[0].0, "1");
    assert_eq!(results[0].1.as_ref().unwrap(), &sample_profile("1"));

    assert_eq!(results[1].0, "missing");
    assert!(results[1].1.is_err());

    assert_eq!(results[2].0, "2");
    assert_eq!(results[2].1.as_ref().unwrap(), &sample_profile("2"));
}

#[test]
fn seconds_until_expiry_counts_down() {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs() as i64;

    let creds = ApiCredentials {
        client_id: "client".to_string(),
        client_secret: "secret".to_string(),
        access_token: "token".to_string(),
        expires_at: now + 120,
    };

    let remaining = creds.seconds_until_expiry();
    assert!((115..=120).contains(&remaining), "remaining was {remaining}");
}

#[test]
fn seconds_until_expiry_clamps_to_zero_when_expired() {
    let creds = ApiCredentials {
        client_id: "client".to_string(),
        client_secret: "secret".to_string(),
        access_token: "token".to_string(),
        expires_at: 0,
    };

    assert_eq!(creds.seconds_until_expiry(), 0);
}

#[test]
fn profile_search_sql_uses_placeholders_not_interpolation() {
    let query = profile_search_sql("Ann", "eng");

    assert!(query.sql.contains("?1"));
    assert!(query.sql.contains("?2"));
    assert!(!query.sql.contains("Ann"));
    assert!(!query.sql.contains("eng"));
    assert_eq!(query.params, vec!["Ann%".to_string(), "eng".to_string()]);
}

#[test]
fn profile_search_sql_keeps_injection_payloads_out_of_the_statement() {
    let query = profile_search_sql("Ann'; DROP TABLE profiles;--", "eng");

    assert!(!query.sql.contains("DROP TABLE"));
    assert_eq!(query.params[0], "Ann'; DROP TABLE profiles;--%");
}

